from fractions import Fraction
from sympy import symbols, diff, simplify, log, exp, sin, cos, tan, atan, asin, sqrt, Abs

x = symbols("x", real=True)
p = symbols("p", positive=True)

def row(kind, n, t):
    # The table: the integrand and its antiderivative, for one term with coefficient 1.
    if kind == "power":
        return t**n, t**(n + 1) / (n + 1)
    if kind == "recip":
        return 1/t, log(Abs(t))
    if kind == "exp":
        return exp(t), exp(t)
    if kind == "base":
        return n**t, n**t / log(n)
    if kind == "sin":
        return sin(t), -cos(t)
    if kind == "cos":
        return cos(t), sin(t)
    if kind == "sec2":
        return 1/cos(t)**2, tan(t)
    if kind == "atan":
        return 1/(1 + t**2), atan(t)
    return 1/sqrt(1 - t**2), asin(t)

def integrate_terms(label, terms):
    print(label)
    f, F, fp, Fp = 0, 0, 0, 0
    for c, kind, n in terms:
        g, G = row(kind, n, x)
        print(f"  {c} * ({g}): the {kind} row gives {c} * ({G})")
        f, F = f + c*g, F + c*G
        g, G = row(kind, n, p)
        fp, Fp = fp + c*g, Fp + c*G
    print(f"  F(x) = {F} + C")
    print(f"  check on x > 0: F' - f simplifies to {simplify(diff(Fp, p) - fp)}")

integrate_terms("Example 1 · the plain case", [[3, "cos", 0], [-2, "exp", 0]])
integrate_terms("Example 3 · a split fraction", [[1, "power", 1], [1, "recip", 0]])
integrate_terms("Example 4 · another base", [[1, "base", 2]])
integrate_terms("Example 5 · inverse trig", [[4, "atan", 0], [1, "asin", 0]])
integrate_terms("Example 6 · tan^2 x as sec^2 x - 1", [[1, "sec2", 0], [-1, "power", 0]])
integrate_terms("Example 7 · 1/x^2 as a power", [[1, "power", -2]])

