from sympy import symbols, sympify, log, exp, sin, cos, tan, atan, asin, Abs

x = symbols("x", real=True)

def antiderivative(kind, n):
    if kind == "power":
        return x**(n + 1) / (n + 1)
    if kind == "recip":
        return log(Abs(x))
    if kind == "exp":
        return exp(x)
    if kind == "base":
        return n**x / log(n)
    if kind == "sin":
        return -cos(x)
    if kind == "cos":
        return sin(x)
    if kind == "sec2":
        return tan(x)
    if kind == "atan":
        return atan(x)
    return asin(x)

k = int(input())
for i in range(k):
    m = int(input())
    F = 0
    for j in range(m):
        words = input().split()
        c = sympify(words[0])
        n = 0
        if len(words) > 2:
            n = sympify(words[2])
        F = F + c * antiderivative(words[1], n)
    print(f"F(x) = {F} + C")

